/* ---------------- widgets ---------------- */
function onTheory(root){
 const w=root.querySelector('#w-map');
 if(w){w.innerHTML=`<b>🎯 Карта-навигатор: нажми на карту</b>${BTNS([['mR','Режим: узнать координаты'],['mG','Игра: найди точку']])}<div id="mP" class="fig" style="cursor:crosshair"></div><div id="mX" style="text-align:center;line-height:1.7;min-height:3em"></div>`;
  let mode='read',target=null,pt=null;const g=id=>w.querySelector('#'+id);const box=[-180,180,86,-72],Wm=600;const P=proj(box,Wm);
  const newT=()=>{target={lat:pick([-50,-40,-30,-20,-10,0,10,20,30,40,50,60]),lon:pick([-150,-120,-90,-60,-30,0,30,60,90,120,150])};};
  const u=()=>{g('mP').innerHTML=worldMap({W:Wm,wd:340,box,grid:30,gridLbl:30,pts:pt?[{lon:pt.lon,lat:pt.lat,r:6}]:[]});setBtns(w,['mR','mG'],mode==='read'?'mR':'mG');
   if(mode==='game'&&!pt)g('mX').innerHTML=`Найди и нажми точку <span class="out">${cfmt(target.lat,target.lon)}</span>`;
   const svg=g('mP').querySelector('svg');svg.addEventListener('click',ev=>{const [x,y]=svgPt(svg,ev);const lon=box[0]+x/P.s,lat=box[2]-y/P.s;if(lon<-180||lon>180||lat>90||lat<-90)return;pt={lat:Math.round(lat),lon:Math.round(lon)};
    if(mode==='read'){u();g('mX').innerHTML=`Координаты: <span class="out">${cfmt(pt.lat,pt.lon)}</span><br><span class="small">${pt.lat>0?'Северное':'Южное'} и ${pt.lon>=0?'Восточное':'Западное'} полушария</span>`;}
    else{const dl=Math.abs(pt.lat-target.lat),dn=Math.abs(pt.lon-target.lon);u();g('mX').innerHTML=`Ты нажал ${cfmt(pt.lat,pt.lon)}. Цель: ${cfmt(target.lat,target.lon)}.<br>${dl<=4&&dn<=4?'<span class="out">🎉 В точку!</span>':`Промах: по широте на ${dl}°, по долготе на ${dn}°.`} <button class="btn ghost" id="mN" type="button">Новая точка</button>`;
     w.querySelector('#mN').onclick=()=>{newT();pt=null;u();};}});};
  g('mR').onclick=()=>{mode='read';pt=null;g('mX').innerHTML='Нажми на любое место карты.';u();};g('mG').onclick=()=>{mode='game';newT();pt=null;u();};
  g('mX').innerHTML='Нажми на любое место карты.';u();}
}

